+fn in_rect(p: P, lo: [f64; 2], hi: [f64; 2]) -> bool {
+    p[0] >= lo[0] - 1e-9 && p[0] <= hi[0] + 1e-9 && p[1] >= lo[1] - 1e-9 && p[1] <= hi[1] + 1e-9
